#include <iostream>
#include <string>

class Account {
public:
    explicit Account(int balance) : balance_(balance) {}
    void deposit(int amount) { balance_ += amount; }
    bool withdraw(int amount) {
        if (amount > balance_) {
            return false;
        }
        balance_ -= amount;
        return true;
    }
    int balance() const { return balance_; }
private:
    int balance_;
};

int main() {
    int initial = 0;
    int n = 0;
    std::cin >> initial >> n;
    Account account(initial);
    for (int i = 0; i < n; i++) {
        std::string op;
        int amount = 0;
        std::cin >> op >> amount;
        if (op == "deposit") {
            account.deposit(amount);
        } else if (op == "withdraw") {
            account.withdraw(amount);
        }
    }
    std::cout << account.balance() << std::endl;
    return 0;
}
